command:
// Applies Taunted to every targeted token, with the token you control as its source.
// Control the taunting creature and target the affected creatures.
//
// duration - when the condition ends:
//   'turn'      → End of the target's next turn
//   'encounter' → End of the encounter
//   'save'      → Save ends
//   null        → Lasts until removed
const duration = 'save';

const sourceToken = canvas.tokens.controlled[0];
const targets     = [...game.user.targets];
if (!sourceToken) { ui.notifications.warn('Control the source token (the taunting creature).'); return; }
if (!targets.length) { ui.notifications.warn('Target one or more tokens to apply Taunted to.'); return; }

const api = game.modules.get('draw-steel-combat-tools').api;
for (const t of targets) {
  await api.applyStatus(t, 'taunted', { source: sourceToken, end: duration });
}
